 if(terminal==='DONE'&&!text(new_publication_id))return {status:'FRESH_CANONICAL_PUBLICATION_REQUIRED',completed:false};
 const r=await db.prepare(`UPDATE v3_recheck_task_shadow SET state=?2,last_result=CASE WHEN ?2='PENDING' AND json_valid(last_result) AND json_extract(last_result,'$.schema')='LIGHT_PRICE_RECHECK_V1' THEN json_set(last_result,'$.full_recheck',json_object('publication_id',?7,'completed_ts',?4,'reason',?8,'authorizes_entry',json('false'))) ELSE json_object('schema','RECHECK_COMPLETION_V1','status',?2,'publication_id',?7,'completed_ts',?4,'reason',?8,'full_analysis_receipt',CASE WHEN json_valid(?9) THEN json(?9) ELSE NULL END,'original_light_price_receipt',CASE WHEN json_valid(last_result) AND json_extract(last_result,'$.schema')='LIGHT_PRICE_RECHECK_V1' THEN json(last_result) ELSE NULL END,'legacy_result',CASE WHEN json_valid(last_result) THEN NULL ELSE last_result END) END,lease_owner=NULL,lease_started_ts=NULL,lease_expires_ts=NULL,updated_ts=?4
 WHERE task_id=?1 AND state='CLAIMED' AND lease_owner=?5 AND lease_started_ts=?6 AND lease_expires_ts>=?4 AND ?4>=lease_started_ts
 AND (?2='EXPIRED' OR expires_ts>?4) AND (?2!='EXPIRED' OR expires_ts<=?4)
 AND (?2!='DONE' OR EXISTS(SELECT 1 FROM canonical_publication_shadow p WHERE p.publication_id=?7 AND p.publication_id!=v3_recheck_task_shadow.publication_id AND p.contract_code=v3_recheck_task_shadow.contract_code AND p.direction=v3_recheck_task_shadow.direction AND p.run_id!=v3_recheck_task_shadow.run_id AND p.observed_ts>=?6 AND p.observed_ts<=?4))`).bind(text(task_id),terminal,text(new_publication_id)||terminal,now,text(actor),claim,text(new_publication_id)||null,text(completion_reason)||null,analysis_receipt?JSON.stringify(analysis_receipt):null).run();
 const changed=Number(r?.meta?.changes??r?.changes??0)===1;return {status:changed?'CLOSED':'NOT_UPDATED',completed:changed,state:changed?terminal:null};
}

